import type { SnapshotSerializer } from 'vitest';

const NG_ATTRIBUTE = /^(ng-reflect-|_nghost-|_ngcontent-)/;
/** Ids generated by Angular Material and CDK, e.g. `mat-input-3`, `cdk-overlay-1`. */
const GENERATED_ID = /^(mat|cdk)-[a-z0-9-]*-\d+$/;
const ID_REFERENCES = ['for', 'aria-labelledby', 'aria-describedby', 'aria-controls', 'aria-owns'];

/** Clones already cleaned, so the serializer does not pick them up again. */
const cleaned = new WeakSet<Element>();

function clean(element: Element): Element {
  const clone = element.cloneNode(true) as Element;
  for (const node of [clone, ...Array.from(clone.querySelectorAll('*'))]) {
    cleaned.add(node);
    for (const name of node.getAttributeNames()) {
      if (NG_ATTRIBUTE.test(name)) node.removeAttribute(name);
    }
    if (GENERATED_ID.test(node.id)) node.removeAttribute('id');
    for (const name of ID_REFERENCES) {
      const value = node.getAttribute(name);
      if (value === null) continue;
      const kept = value.split(/\s+/).filter((id) => id && !GENERATED_ID.test(id));
      if (kept.length) node.setAttribute(name, kept.join(' '));
      else node.removeAttribute(name);
    }
  }
  return clone;
}

/**
 * Vitest snapshot serializer for DOM elements. It removes noise that changes between
 * runs or Angular versions: `ng-reflect-*`, `_nghost-*` and `_ngcontent-*` attributes, and
 * generated Material/CDK ids (`mat-input-3`, `cdk-overlay-1`) together with their references
 * in `for`, `aria-labelledby`, `aria-describedby`, `aria-controls` and `aria-owns`.
 * The element under test is not changed, a clone is serialized.
 *
 * @example
 * ```ts
 * expect.addSnapshotSerializer(ngDomSnapshotSerializer);
 * ```
 */
export const ngDomSnapshotSerializer: SnapshotSerializer = {
  test: (value: unknown) => value instanceof Element && !cleaned.has(value),
  serialize: (value, config, indentation, depth, refs, printer) => printer(clean(value as Element), config, indentation, depth, refs),
};
